from collections import deque

def get_components(grid, val):
    """Get connected cells for a given value"""
    height = len(grid)
    width = len(grid[0])
    components = []
    visited = set()

    for r in range(height):
        for c in range(width):
            if grid[r][c] == val and (r, c) not in visited:
                comp = []
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    comp.append((cr, cc))
                    # Check neighbors
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width:
                            if grid[nr][nc] == val and (nr, nc) not in visited:
                                queue.append((nr, nc))
                components.append(comp)

    return components

