                if 0 <= nr < 14 and 0 <= nc < len(grid[nr]) and grid[nr][nc] == val and (nr, nc) not in visited_local:
                    stack.append((nr, nc))

        if len(comp) < 3:
            continue

        rows = set(r for r,c in comp)
        cols = list(set(c for r,c in comp))
        if max(rows) != min(rows):
            continue  # Not a horizontal bar (same row)

        row = list(rows)[0]
        if max(cols) - min(cols) >= 3:
            bar_key = (val, row, min(cols), max(cols))
            horizontal_bars.append({'val': val, 'row': row, 'key': bar_key, 'comp': comp})

print(f"\nHorizontal bars: {len(horizontal_bars)}")
for hb in horizontal_bars:
    print(f"  {hb['key']}")

# Apply transformation
output = [row[:] for row in grid]
