    bar_key = hb['key']
    bar_row = bar_key[1]
    bar_comp_comp = hb['comp']

    comp_ids = [cell_to_comp_id[cell] for cell in bar_comp_comp]

    under_cells = []
    for r in range(bar_row + 1, 14):
        for c in range(bar_key[2], bar_key[3] + 1):
            if c < len(grid[r]) and grid[r][c] != 8:
                under_cells.append((r, c))

    comp_ids_under = set()
    for cell in under_cells:
        cid = cell_to_comp_id.get(cell)
        if cid:
            comp_ids_under.add(cid)

    for cid in comp_ids_under:
        # Transform entire component
        comp_cells = [c for c, c_id in cell_to_comp_id.items() if c_id == cid]
        for cell in comp_cells:
            r, c = cell
            if c < len(output[r]):
                output[r][c] = bar_val
                changes_list.append((r, c, grid_original[r][c] if (r, c) in grid_original else 'N/A', bar_val))

# Get original for changes
orig_output = [row[:] for row in grid]
