for r in range(14):
    for c in range(len(grid[r])):
        if grid[r][c] != output[r][c]:
            changes_list.append((r, c, grid[r][c], output[r][c]))

print(f"\nChanges: {len(changes_list)}")
for r, c, orig, new in changes_list:
    print(f"  ({r},{c}): {orig} → {new}")

